CREATE TABLE public.contas_caixa(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),nome text NOT NULL,tipo text NOT NULL DEFAULT 'banco' CHECK(tipo IN('banco','dinheiro','digital')),saldo_inicial numeric(12,2),data_saldo_inicial date,ativa boolean NOT NULL DEFAULT true,criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.contas_caixa TO authenticated;
GRANT ALL ON public.contas_caixa TO service_role;
ALTER TABLE public.contas_caixa ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner cash accounts" ON public.contas_caixa FOR ALL TO authenticated USING(public.has_owner_access() AND user_id=auth.uid()) WITH CHECK(public.has_owner_access() AND user_id=auth.uid());
CREATE UNIQUE INDEX contas_caixa_nome ON public.contas_caixa(user_id,lower(trim(nome)));
ALTER TABLE public.lancamentos ADD COLUMN caixa_owner_id uuid DEFAULT auth.uid();
ALTER TABLE public.lancamentos ADD COLUMN conta_id uuid REFERENCES public.contas_caixa(id);
ALTER TABLE public.lancamentos ADD COLUMN situacao text NOT NULL DEFAULT 'realizado' CHECK(situacao IN('realizado','pendente','cancelado','estornado'));
ALTER TABLE public.lancamentos ADD COLUMN data_pagamento date;
ALTER TABLE public.lancamentos ADD COLUMN aluno_id uuid REFERENCES public.alunos(id);
ALTER TABLE public.lancamentos ADD COLUMN referencia_mensalidade text;
ALTER TABLE public.lancamentos ADD COLUMN transferencia_id uuid;
ALTER TABLE public.lancamentos ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
UPDATE public.lancamentos SET caixa_owner_id='03ee28fb-62ce-4919-8747-aba6891b8f1a',data_pagamento=data_lancamento WHERE EXISTS(SELECT 1 FROM public.user_roles WHERE user_id='03ee28fb-62ce-4919-8747-aba6891b8f1a' AND role='owner');
ALTER POLICY "Owner only cash entries" ON public.lancamentos USING(public.has_owner_access() AND caixa_owner_id=auth.uid()) WITH CHECK(public.has_owner_access() AND caixa_owner_id=auth.uid());
CREATE INDEX lancamentos_conta_data ON public.lancamentos(conta_id,data_pagamento);
CREATE TABLE public.conferencias_caixa(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conta_id uuid REFERENCES public.contas_caixa(id),data_referencia date NOT NULL,saldo_informado numeric(12,2) NOT NULL,saldo_sistema numeric(12,2) NOT NULL,diferenca numeric(12,2) NOT NULL,status text NOT NULL CHECK(status IN('ok','divergente')),observacao text NOT NULL DEFAULT '',criado_por uuid NOT NULL DEFAULT auth.uid(),criado_em timestamptz NOT NULL DEFAULT now(),resolvida boolean NOT NULL DEFAULT false,resolvida_em timestamptz);
GRANT SELECT ON public.conferencias_caixa TO authenticated;
GRANT ALL ON public.conferencias_caixa TO service_role;
ALTER TABLE public.conferencias_caixa ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner cash checks" ON public.conferencias_caixa FOR SELECT TO authenticated USING(public.has_owner_access() AND criado_por=auth.uid());
CREATE TABLE public.caixa_alteracoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lancamento_id uuid NOT NULL,conferencias_ids uuid[] NOT NULL DEFAULT '{}',operacao text NOT NULL,valor_antigo numeric(12,2),valor_novo numeric(12,2),antes jsonb,depois jsonb,criado_por uuid NOT NULL,criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.caixa_alteracoes TO authenticated;
GRANT ALL ON public.caixa_alteracoes TO service_role;
ALTER TABLE public.caixa_alteracoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner cash audit" ON public.caixa_alteracoes FOR SELECT TO authenticated USING(public.has_owner_access() AND criado_por=auth.uid());
CREATE OR REPLACE FUNCTION public.caixa_validar_conta() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.nome:=trim(NEW.nome); IF NEW.nome='' THEN RAISE EXCEPTION 'Informe o nome da conta.'; END IF; IF (NEW.saldo_inicial IS NULL)<>(NEW.data_saldo_inicial IS NULL) THEN RAISE EXCEPTION 'Informe saldo inicial e sua data juntos, ou deixe ambos vazios.'; END IF; IF TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Não é possível mudar o responsável da conta.'; END IF; IF NEW.saldo_inicial::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Saldo inicial inválido.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER caixa_validar_conta BEFORE INSERT OR UPDATE ON public.contas_caixa FOR EACH ROW EXECUTE FUNCTION public.caixa_validar_conta();
CREATE OR REPLACE FUNCTION public.caixa_validar_lancamento() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.contas_caixa; fechadas uuid[]; uid uuid; BEGIN
uid:=CASE WHEN TG_OP='DELETE' THEN OLD.caixa_owner_id ELSE NEW.caixa_owner_id END;
PERFORM pg_advisory_xact_lock(hashtextextended('caixa:'||coalesce(uid::text,''),0));
IF TG_OP<>'DELETE' THEN
 IF NEW.conta_id IS NOT NULL THEN SELECT * INTO c FROM public.contas_caixa WHERE id=NEW.conta_id; IF c.id IS NULL OR c.user_id IS DISTINCT FROM NEW.caixa_owner_id THEN RAISE EXCEPTION 'Conta não pertence à escola autorizada.'; END IF; IF NOT c.ativa AND (TG_OP='INSERT' OR NEW.conta_id IS DISTINCT FROM OLD.conta_id) THEN RAISE EXCEPTION 'Esta conta está desativada.'; END IF; END IF;
 IF TG_OP='UPDATE' AND NEW.caixa_owner_id IS DISTINCT FROM OLD.caixa_owner_id THEN RAISE EXCEPTION 'Não é possível mudar o responsável.'; END IF;
 IF NEW.situacao='realizado' AND NEW.data_pagamento IS NULL THEN NEW.data_pagamento:=NEW.data_lancamento; END IF;
 IF NEW.situacao='realizado' AND NEW.data_pagamento IS NULL THEN RAISE EXCEPTION 'Informe data do pagamento ou recebimento.'; END IF;
 IF NEW.referencia_mensalidade IS NOT NULL AND (NEW.referencia_mensalidade !~ '^\d{4}-(0[1-9]|1[0-2])$' OR NEW.aluno_id IS NULL OR NEW.tipo<>'entrada') THEN RAISE EXCEPTION 'Vínculo de mensalidade inválido.'; END IF;
 IF NEW.valor::text IN('NaN','Infinity','-Infinity') OR NEW.valor<0 OR round(NEW.valor,2)<>NEW.valor THEN RAISE EXCEPTION 'Informe um valor válido com até dois centavos.'; END IF;
 NEW.updated_at:=now();
END IF;
IF TG_OP<>'INSERT' AND auth.uid() IS NOT NULL THEN
 SELECT array_agg(id) INTO fechadas FROM public.conferencias_caixa WHERE criado_por=auth.uid() AND (status='ok' OR resolvida) AND (conta_id IS NULL OR conta_id=OLD.conta_id OR (TG_OP='UPDATE' AND conta_id=NEW.conta_id)) AND (coalesce(OLD.data_pagamento,OLD.data_lancamento)<=data_referencia OR (TG_OP='UPDATE' AND coalesce(NEW.data_pagamento,NEW.data_lancamento)<=data_referencia));
 IF fechadas IS NOT NULL AND coalesce(current_setting('app.caixa_confirmado',true),'')<>'sim' THEN RAISE EXCEPTION 'Este lançamento afeta uma conferência fechada. Confirme a alteração.'; END IF;
END IF;
IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER zzzz_caixa_validar_lancamento BEFORE INSERT OR UPDATE OR DELETE ON public.lancamentos FOR EACH ROW EXECUTE FUNCTION public.caixa_validar_lancamento();
CREATE OR REPLACE FUNCTION public.caixa_auditar_lancamento() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fechadas uuid[]; BEGIN IF auth.uid() IS NOT NULL THEN SELECT array_agg(id) INTO fechadas FROM public.conferencias_caixa WHERE criado_por=auth.uid() AND (status='ok' OR resolvida) AND (conta_id IS NULL OR conta_id=OLD.conta_id OR (TG_OP='UPDATE' AND conta_id=NEW.conta_id)) AND coalesce(OLD.data_pagamento,OLD.data_lancamento)<=data_referencia; INSERT INTO public.caixa_alteracoes(lancamento_id,conferencias_ids,operacao,valor_antigo,valor_novo,antes,depois,criado_por) VALUES(OLD.id,coalesce(fechadas,'{}'),TG_OP,OLD.valor,CASE WHEN TG_OP='UPDATE' THEN NEW.valor END,to_jsonb(OLD),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(NEW) END,auth.uid()); END IF; RETURN NULL; END $$;
CREATE TRIGGER caixa_auditar_lancamento AFTER UPDATE OR DELETE ON public.lancamentos FOR EACH ROW EXECUTE FUNCTION public.caixa_auditar_lancamento();
CREATE OR REPLACE FUNCTION public.caixa_conferir(p_conta uuid,p_data date,p_saldo numeric,p_observacao text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE saldo numeric(12,2); cid uuid; BEGIN
IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF;
IF p_data IS NULL OR p_saldo IS NULL OR p_saldo::text IN('NaN','Infinity','-Infinity') OR round(p_saldo,2)<>p_saldo THEN RAISE EXCEPTION 'Informe data e saldo válidos com até dois centavos.'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('caixa:'||auth.uid()::text,0));
PERFORM 1 FROM public.contas_caixa WHERE user_id=auth.uid() AND (p_conta IS NULL OR id=p_conta) FOR SHARE;
IF NOT FOUND THEN RAISE EXCEPTION 'Cadastre ou selecione uma conta.'; END IF;
IF EXISTS(SELECT 1 FROM public.contas_caixa WHERE user_id=auth.uid() AND (p_conta IS NULL OR id=p_conta) AND (saldo_inicial IS NULL OR data_saldo_inicial IS NULL OR data_saldo_inicial>p_data)) THEN RAISE EXCEPTION 'Conta sem saldo inicial válido: informe saldo e data antes de conferir.'; END IF;
IF p_conta IS NULL AND EXISTS(SELECT 1 FROM public.lancamentos WHERE caixa_owner_id=auth.uid() AND conta_id IS NULL AND situacao='realizado' AND data_pagamento<=p_data) THEN RAISE EXCEPTION 'Há lançamentos sem conta definida. Vincule-os antes de conferir todas as contas.'; END IF;
SELECT sum(c.saldo_inicial+coalesce((SELECT sum(CASE WHEN l.tipo='entrada' THEN l.valor ELSE -l.valor END) FROM public.lancamentos l WHERE l.conta_id=c.id AND l.caixa_owner_id=auth.uid() AND l.situacao='realizado' AND l.data_pagamento>c.data_saldo_inicial AND l.data_pagamento<=p_data),0)) INTO saldo FROM public.contas_caixa c WHERE c.user_id=auth.uid() AND (p_conta IS NULL OR c.id=p_conta);
INSERT INTO public.conferencias_caixa(conta_id,data_referencia,saldo_informado,saldo_sistema,diferenca,status,observacao,criado_por) VALUES(p_conta,p_data,p_saldo,saldo,p_saldo-saldo,CASE WHEN p_saldo=saldo THEN 'ok' ELSE 'divergente' END,coalesce(p_observacao,''),auth.uid()) RETURNING id INTO cid; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.caixa_conferir(uuid,date,numeric,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.caixa_conferir(uuid,date,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.caixa_resolver(p_id uuid,p_observacao text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; UPDATE public.conferencias_caixa SET observacao=coalesce(p_observacao,''),resolvida=true,resolvida_em=now() WHERE id=p_id AND criado_por=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Conferência não encontrada.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.caixa_resolver(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.caixa_resolver(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.caixa_salvar_lancamento(p_row jsonb,p_excluir boolean DEFAULT false,p_confirmar boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE lid uuid; atual public.lancamentos; BEGIN
IF NOT public.has_owner_access() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('caixa:'||auth.uid()::text,0)); lid:=nullif(p_row->>'id','')::uuid; IF p_confirmar THEN PERFORM set_config('app.caixa_confirmado','sim',true); END IF;
IF lid IS NOT NULL THEN SELECT * INTO atual FROM public.lancamentos WHERE id=lid AND caixa_owner_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Lançamento não encontrado.'; END IF; IF atual.transferencia_id IS NOT NULL THEN RAISE EXCEPTION 'Não altere só um lado da transferência. Registre uma transferência inversa.'; END IF; IF p_excluir THEN DELETE FROM public.lancamentos WHERE id=lid; RETURN lid; END IF;
atual:=jsonb_populate_record(atual,p_row); UPDATE public.lancamentos SET mes=atual.mes,data_lancamento=atual.data_lancamento,tipo=atual.tipo,grupo=atual.grupo,categoria=atual.categoria,valor=atual.valor,descricao=atual.descricao,conta_id=atual.conta_id,situacao=atual.situacao,data_pagamento=atual.data_pagamento,aluno_id=atual.aluno_id,referencia_mensalidade=atual.referencia_mensalidade WHERE id=lid;
ELSE IF p_excluir THEN RAISE EXCEPTION 'Lançamento não encontrado.'; END IF; INSERT INTO public.lancamentos(mes,data_lancamento,tipo,grupo,categoria,valor,descricao,conta_id,situacao,data_pagamento,aluno_id,referencia_mensalidade) VALUES(p_row->>'mes',(p_row->>'data_lancamento')::date,p_row->>'tipo',coalesce(p_row->>'grupo',''),p_row->>'categoria',(p_row->>'valor')::numeric,p_row->>'descricao',nullif(p_row->>'conta_id','')::uuid,coalesce(p_row->>'situacao','realizado'),nullif(p_row->>'data_pagamento','')::date,nullif(p_row->>'aluno_id','')::uuid,nullif(p_row->>'referencia_mensalidade','')) RETURNING id INTO lid; END IF; RETURN lid; END $$;
REVOKE ALL ON FUNCTION public.caixa_salvar_lancamento(jsonb,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.caixa_salvar_lancamento(jsonb,boolean,boolean) TO authenticated;